from pathlib import Path


def edit(path, replacements):
    p = Path(path)
    text = p.read_text()
    for label, old, new in replacements:
        n = text.count(old)
        if n != 1:
            raise SystemExit(f"{path} / {label}: expected 1 match, found {n}")
        text = text.replace(old, new, 1)
    p.write_text(text)


